const tabId = 583778164;
const newsDetails = await browserjs(tabId, () => {
  // Find heading with text "News stories"
  const headings = Array.from(document.querySelectorAll('*')).filter(el => {
    return el.children.length === 0 && (el.textContent.trim() === 'News stories' || el.textContent.trim() === 'Top stories' || el.textContent.trim() === 'News');
  });

  const info = headings.map(h => {
    let parent = h.parentElement;
    // Walk up until we find a container with links or articles
    for (let i = 0; i < 5; i++) {
      if (!parent) break;
      const links = Array.from(parent.querySelectorAll('a')).filter(a => !a.href.includes('google.com/finance'));
      if (links.length > 0) {
        return {
          heading: h.textContent.trim(),
          containerClass: parent.className,
          articles: links.map(a => ({
            text: a.innerText.trim(),
            href: a.href,
            source: a.closest('div')?.innerText?.slice(0, 100)
          }))
        };
      }
      parent = parent.parentElement;
    }
    return { heading: h.textContent.trim(), notFound: true };
  });

  return info;
});

